function showTermArchive(archiveId) {
  const archive=data().termArchives.find(a=>a.id===archiveId);if(!archive)throw new Error('Terminsarkivet hittades inte.');
  const snapshot=archive.data,sessions=[...snapshot.sessions].sort((a,b)=>b.date.localeCompare(a.date)||b.start.localeCompare(a.start)),students=snapshot.classes.reduce((n,c)=>n+c.students.length,0);
  const classRows=snapshot.classes.map(c=>`<li><strong>${esc(c.name)}</strong> · Årskurs ${c.yearGroup||'ej angiven'} · ${c.students.length} elever</li>`).join('');
  const recent=sessions.slice(0,12).map(s=>`<li><strong>${esc(formatDate(s.date))} · ${esc(s.className||snapshot.classes.find(c=>c.id===s.classId)?.name||'Klass')}</strong><small>${esc(s.topic||'Idrott & hälsa')} · ${esc(s.start)}–${esc(s.end)}</small></li>`).join('');
  showDialog(`${esc(archive.label)} · Arkiv`,`${snapshot.classes.length} klasser · ${students} elever · ${sessions.length} sparade lektioner`,
    `<h3>Klasser</h3><ul class="archive-class-list">${classRows||'<li>Inga klasser</li>'}</ul><h3 class="section-space">Senaste lektionerna</h3><ul class="archive-session-list">${recent||'<li>Inga sparade lektioner</li>'}</ul><p class="helper space-top">Arkivet är skrivskyddat. Hämta en fullständig arkivkopia för att behålla eller flytta alla detaljer.</p>`,
    `${btn('Stäng','close-modal')}${btn(`${icon('download',14)} Ladda ner hela arkivet`,'download-term-archive','primary',`data-id="${esc(archiveId)}"`)}`);
}
